//! osis-app: the first-party osis app (notes/app.md). `data` is the toolkit-free actions layer
//! (every intent becomes osis reads and writes there), `demo` the demo data, `ui` the Masonry
//! window over kit.
#![forbid(unsafe_code)]

pub mod data;
pub mod demo;
pub mod edit;
pub mod ui;

/// Typed keys of the app's schema (schema/osis-app.osis, generated by build.rs).
#[allow(dead_code, clippy::all)]
pub mod schema {
    use osis::schema as osis_schema;
    include!(concat!(env!("OUT_DIR"), "/osis_app.rs"));
}

/// Typed keys of schema/event.osis.
#[allow(dead_code, clippy::all)]
pub mod event {
    use osis::schema as osis_schema;
    include!(concat!(env!("OUT_DIR"), "/event.rs"));
}

/// Typed keys of schema/contact.osis.
#[allow(dead_code, clippy::all)]
pub mod contact {
    use osis::schema as osis_schema;
    include!(concat!(env!("OUT_DIR"), "/contact.rs"));
}
